    void knead() const { cout << "踩奶 " << times << " 回" << endl; }
};

class Baby : public Purr, public Knead {
public:
    Baby(int k) : Purr(k), Knead(k) { cout << "最后搭它自己那一半" << endl; }
};

int main() {
    int n = 0;
    cin >> n;

    Baby b(n);
    b.purr();
    b.knead();
    return 0;
}
